class Solution:
    def maxNonOverlapping(self, nums: List[int], target: int) -> int:
        n, i, ans = len(nums), 0, 0
        while i < n:
            s = 0
            j = i
            while j < n:
                s += nums[j]
                if s == target:
                    ans += 1
                    break
                j += 1
            i = j + 1
        return ans

