class Solution {
public:
    int maxNonOverlapping(vector<int>& nums, int target) {
        int n = nums.size(), i = 0, ans = 0;
        while (i < n) {
            long long s = 0;
            int j = i;
            while (j < n) {
                s += nums[j];
                if (s == target) { ans++; break; }
                j++;
            }
            i = j + 1;
        }
        return ans;
    }
};

