class Solution {
public:
    int maxNonOverlapping(vector<int>& nums, int target) {
        unordered_set<long long> seen{0};
        long long prefix = 0;
        int ans = 0;
        for (int x : nums) {
            prefix += x;
            if (seen.count(prefix - target)) {
                ans++;
                seen = {0LL};
                prefix = 0;
            } else {
                seen.insert(prefix);
            }
        }
        return ans;
    }
};

