class Solution {
    public int maxNonOverlapping(int[] nums, int target) {
        Set<Long> seen = new HashSet<>();
        seen.add(0L);
        long prefix = 0;
        int ans = 0;
        for (int x : nums) {
            prefix += x;
            if (seen.contains(prefix - target)) {
                ans++;
                seen.clear();
                seen.add(0L);
                prefix = 0;
            } else {
                seen.add(prefix);
            }
        }
        return ans;
    }
}

